diff --git a/src/index.css b/src/index.css
index 43a4bb2..2a746c7 100644
--- a/src/index.css
+++ b/src/index.css
@@ -4,6 +4,100 @@ body {

 .page {
   min-height: 100vh;
+  box-sizing: border-box;
   display: grid;
   place-items: center;
+  padding: var(--g-spacing-5);
+  background:
+    radial-gradient(ellipse at 15% 12%, var(--g-color-base-selection) 0, transparent 35%),
+    var(--g-color-base-background);
+}
+
+.login-card {
+  box-sizing: border-box;
+  width: min(100%, 440px);
+  padding: clamp(var(--g-spacing-5), 7vw, var(--g-spacing-8));
+  border: 1px solid var(--g-color-line-generic);
+  border-radius: var(--g-border-radius-xl);
+  background: var(--g-color-base-background);
+}
+
+.login-mark {
+  display: flex;
+  align-items: center;
+  gap: var(--g-spacing-1);
+  width: fit-content;
+  margin-bottom: var(--g-spacing-6);
+}
+
+.login-mark span {
+  display: block;
+  width: var(--g-spacing-1);
+  height: var(--g-spacing-3);
+  border-radius: var(--g-border-radius-s);
+  background: var(--g-color-base-brand);
+}
+
+.login-mark span:nth-child(2) {
+  height: var(--g-spacing-5);
+}
+
+.eyebrow {
+  letter-spacing: 0.08em;
+}
+
+.login-title {
+  margin: var(--g-spacing-2) 0 0;
+}
+
+.login-description {
+  display: block;
+  margin-top: var(--g-spacing-2);
+}
+
+.login-form {
+  display: flex;
+  flex-direction: column;
+  gap: var(--g-spacing-4);
+  margin-top: var(--g-spacing-7);
+}
+
+.field {
+  display: flex;
+  flex-direction: column;
+  gap: var(--g-spacing-2);
+}
+
+.field-label {
+  color: var(--g-color-text-primary);
+}
+
+.login-control {
+  width: 100%;
+}
+
+.login-options {
+  display: flex;
+  align-items: center;
+  margin-top: calc(-1 * var(--g-spacing-1));
+}
+
+.login-submit {
+  margin-top: var(--g-spacing-1);
+}
+
+.login-footer {
+  display: block;
+  margin-top: var(--g-spacing-6);
+  text-align: center;
+}
+
+@media (max-width: 480px) {
+  .page {
+    padding: var(--g-spacing-3);
+  }
+
+  .login-card {
+    padding: var(--g-spacing-5);
+  }
 }
